(async()=>{const {client,escape:esc,safeURL}=PortfolioCMS;const root=document.querySelector('#blog-content');const quiet=(title,text)=>{root.innerHTML=`<section class="blog-state"><span class="eyebrow">NOTES / IDEAS / EXPLORATIONS</span><h1>${esc(title)}</h1><p>${esc(text)}</p><a class="button dark" href="/">Explore the portfolio <span>↗</span></a></section>`};try{const settings=await PortfolioCMS.getSettings();if(!settings.blogs_enabled){quiet('A quiet page, for now.','The blog is currently disabled. You can still explore my projects and research on the portfolio.');return}const slug=new URLSearchParams(location.search).get('post');if(slug){const {data:post,error}=await client.from('portfolio_posts').select('*').eq('slug',slug).eq('published',true).eq('archived',false).maybeSingle();if(error)throw error;if(!post){quiet('This note isn’t here.','It may be unpublished or the address may have changed.');return}document.title=post.title+' — Sathwik Tadivaka';root.innerHTML=`<article class="blog-article"><a class="text-link" href="/blogs/">← All notes</a><h1>${esc(post.title)}</h1><time datetime="${esc(post.published_at)}">${esc(new Date(post.published_at).toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'}))}</time>${!post.body_html?`<p class="blog-intro">${esc(post.excerpt)}</p>`:''}${safeURL(post.cover_url)?`<img src="${esc(safeURL(post.cover_url))}" alt="${esc(post.title)}">`:''}<div class="rich-content">${BlogContent.render(post)}</div></article>`}else{const {data:posts,error}=await client.from('portfolio_posts').select('id,title,slug,excerpt,cover_url,published_at').eq('published',true).eq('archived',false).order('published_at',{ascending:false});if(error)throw error;root.innerHTML=`<div class="blog-heading"><div><span class="eyebrow">NOTES FROM THE WORKBENCH</span><h1>A thought.<br><em>Then another.</em></h1></div><p>Things I’m learning, questions I’m following, and ideas worth putting into words.</p></div>${posts.length?`<div class="blog-grid">${posts.map(p=>`<a class="blog-card" href="/blogs/?post=${encodeURIComponent(p.slug)}">${safeURL(p.cover_url)?`<img src="${esc(safeURL(p.cover_url))}" alt="${esc(p.title)}" loading="lazy">`:'<div class="blog-placeholder" aria-hidden="true">✳</div>'}<h2>${esc(p.title)} ↗</h2><p>${esc(p.excerpt)}</p><small>${esc(new Date(p.published_at).toLocaleDateString('en-IN',{month:'short',day:'numeric',year:'numeric',timeZone:'Asia/Kolkata'}))}</small></a>`).join('')}</div>`:'<p class="cms-empty">The first note is still taking shape. Come back soon.</p>'}`;}document.querySelector('meta[name=robots]').content='index,follow';}catch(error){quiet('A small pause.','The blog could not load right now. Please try again in a moment.');}})();
